const statusLabel: Record<string, string> = {
  bozza: 'Bozza', preventivo_inviato: 'Preventivo inviato', in_attesa: 'In attesa', confermato: 'Confermato', in_produzione: 'In produzione', eseguito: 'Eseguito', chiuso: 'Chiuso', annullato: 'Annullato'
}

function nameOfClient(c?: Client | null) { if (!c) return 'Cliente non assegnato'; return c.company_name || [c.first_name, c.last_name].filter(Boolean).join(' ') || 'Cliente' }
function euro(v: number | null | undefined, decimals = 2) { return new Intl.NumberFormat('it-IT', { style: 'currency', currency: 'EUR', minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(Number(v || 0)) }
const quotationMonths=['GEN','FEB','MAR','APR','MAG','GIU','LUG','AGO','SET','OTT','NOV','DIC']; function quotationLabel(value?: string | null) { if (!value) return ''; const d=new Date(value+'T12:00:00'); if(Number.isNaN(d.getTime())) return ''; return `${quotationMonths[d.getMonth()]}${String(d.getFullYear()).slice(-2)}` } function normalizeQuotationInput(value:string){return value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,5)} function quotationToDate(value:string){const clean=normalizeQuotationInput(value);const m=clean.slice(0,3), y=clean.slice(3);const month=quotationMonths.indexOf(m);if(month<0||!/^[0-9]{2}$/.test(y))return null;return `20${y}-${String(month+1).padStart(2,'0')}-01`}
const factorToBase: Record<string, number> = { kg: 1000, g: 1, l: 1000, ml: 1, pz: 1 }
const family: Record<string, string> = { kg: 'mass', g: 'mass', l: 'volume', ml: 'volume', pz: 'count' }
function convertQuantity(qty: number, fromCode?: string | null, toCode?: string | null) { if (!fromCode || !toCode || fromCode === toCode) return qty; if (family[fromCode] !== family[toCode]) return qty; return qty * factorToBase[fromCode] / factorToBase[toCode] }
function lineCost(line: RecipeLine) { const ingredient = line.ingredient; if (!ingredient) return 0; const from = line.unit?.code || ingredient.unit?.code || null; const to = ingredient.unit?.code || from; return convertQuantity(Number(line.quantity || 0), from, to) * Number(ingredient.current_price || 0) }
function recipeCost(recipe: Recipe) { return (recipe.recipe_ingredients || []).reduce((sum, l) => sum + lineCost(l), 0) }
function suggestedPrice(recipe: Recipe) { const target = Number(recipe.target_food_cost_percent || 0); if (!target) return 0; return recipeCost(recipe) / (target / 100) }

export default function Home() {
  const [sessionReady, setSessionReady] = useState(false); const [signedIn, setSignedIn] = useState(false); const [userEmail,setUserEmail]=useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [authMessage, setAuthMessage] = useState(''); const [section, setSection] = useState<Section>('dashboard'); const [sidebar, setSidebar] = useState(false); const [clients, setClients] = useState<Client[]>([]); const [events, setEvents] = useState<EventRow[]>([]); const [units, setUnits] = useState<Unit[]>([]); const [ingredients, setIngredients] = useState<Ingredient[]>([]); const [recipes, setRecipes] = useState<Recipe[]>([]); const [loading, setLoading] = useState(false); const [query, setQuery] = useState(''); const [modal, setModal] = useState<ModalName>(null); const [editingEvent, setEditingEvent] = useState<EventRow | null>(null); const [editingClient, setEditingClient] = useState<Client | null>(null); const [editingIngredient, setEditingIngredient] = useState<Ingredient | null>(null); const [newRecipeCollection,setNewRecipeCollection]=useState<RecipeCollection>('banquets'); const [editingRecipe, setEditingRecipe] = useState<Recipe | null>(null)
  useEffect(() => { if (!supabase) { setSessionReady(true); return }; supabase.auth.getSession().then(({ data }) => { setSignedIn(Boolean(data.session)); setUserEmail(data.session?.user?.email||''); setSessionReady(true) }); const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {setSignedIn(Boolean(session));setUserEmail(session?.user?.email||'')}); return () => listener.subscription.unsubscribe() }, [])
  useEffect(() => { if (signedIn) refreshAll() }, [signedIn])
  const kitchenMode=userEmail.toLowerCase()==='cucina@officinaventidue.it';
  useEffect(()=>{if(kitchenMode)setSection('events')},[kitchenMode])
  async function refreshAll() { if (!supabase) return; setLoading(true); const [c,e,u,i,r]=await Promise.all([supabase.from('clients').select('*').order('created_at',{ascending:false}),supabase.from('events').select('*, client:clients(*)').order('event_date',{ascending:true}),supabase.from('units').select('id,code,name').order('code'),supabase.from('ingredients').select('id,ingredient_number,name,category,current_price,current_price_date,unit_id,active,unit:units(id,code,name)').order('name'),supabase.from('recipes').select('id,recipe_collection,recipe_number,name,category,description,procedure,equipment,allergens,notes,standard_portions,target_food_cost_percent,manual_sale_price,active,recipe_ingredients(id,recipe_id,ingredient_id,quantity,unit_id,sort_order,ingredient:ingredients(id,ingredient_number,name,category,current_price,unit_id,active,unit:units(id,code,name)),unit:units(id,code,name))').order('name')]); if(c.data)setClients(c.data as Client[]);if(e.data)setEvents(e.data as any);if(u.data)setUnits(u.data as Unit[]);if(i.data)setIngredients(i.data as any);if(r.data)setRecipes(r.data as any);setLoading(false) }
  async function signIn(e:FormEvent){e.preventDefault();if(!supabase)return;setAuthMessage('Accesso in corso…');const{error}=await supabase.auth.signInWithPassword({email,password});setAuthMessage(error?error.message:'')}
  async function logout(){await supabase?.auth.signOut()}
  const today=new Date().toISOString().slice(0,10);const upcoming=events.filter(e=>e.event_date>=today&&e.status!=='annullato').slice(0,6);const confirmed=events.filter(e=>e.event_date>=today&&e.status==='confermato').length;const waiting=events.filter(e=>['preventivo_inviato','in_attesa'].includes(e.status)).length;const monthPrefix=today.slice(0,7);const monthEvents=events.filter(e=>e.event_date.startsWith(monthPrefix)&&e.status!=='annullato').length
  if(!configured)return <SetupScreen/>;if(!sessionReady)return <div className="centerScreen"><div className="spinner"/></div>;if(!signedIn)return <Login email={email} password={password} setEmail={setEmail} setPassword={setPassword} submit={signIn} message={authMessage}/>
  if(kitchenMode)return <KitchenHome events={events} recipes={recipes} loading={loading} logout={logout}/>
  return <div className="appShell"><aside className={sidebar?'sidebar open':'sidebar'}><div className="brand"><div className="brandMark">22</div><div><strong>Orders NG</strong><span>Officina22</span></div><button className="mobileClose" onClick={()=>setSidebar(false)}><X/></button></div><nav>{sections.map(s=>{const Icon=s.icon;return <button key={s.id} className={section===s.id?'navItem active':'navItem'} onClick={()=>{setSection(s.id);setSidebar(false)}}><Icon size={19}/><span>{s.label}</span></button>})}</nav><div className="sidebarBottom"><button className="navItem" onClick={logout}><LogOut size={19}/><span>Esci</span></button></div></aside>{sidebar&&<div className="scrim" onClick={()=>setSidebar(false)}/>}<main className="main"><header className="topbar"><button className="menuButton" onClick={()=>setSidebar(true)}><Menu/></button><div><span className="eyebrow">ORDERS NG</span><h1>{sections.find(s=>s.id===section)?.label}</h1></div></header><div className="content">{loading&&<div className="loadingLine"/>}{section==='dashboard'&&<Dashboard upcoming={upcoming} confirmed={confirmed} waiting={waiting} monthEvents={monthEvents} onOpen={(e:EventRow)=>{setEditingEvent(e);setModal('event')}} onSection={setSection}/>} {section==='events'&&<Events events={events} query={query} setQuery={setQuery} onNew={()=>{setEditingEvent(null);setModal('event')}} onOpen={(e:EventRow)=>{setEditingEvent(e);setModal('event')}}/>}{section==='clients'&&<Clients clients={clients} query={query} setQuery={setQuery} onNew={()=>{setEditingClient(null);setModal('client')}} onOpen={(c:Client)=>{setEditingClient(c);setModal('client')}}/>}{section==='recipes'&&<Recipes recipes={recipes} onAssociations={()=>setSection('carte-associations')} onNew={(collection:RecipeCollection)=>{setNewRecipeCollection(collection);setEditingRecipe(null);setModal('recipe')}} onOpen={(r:Recipe)=>{setEditingRecipe(r);setModal('recipe')}}/>}{section==='ingredients'&&<Ingredients ingredients={ingredients} onNew={()=>{setEditingIngredient(null);setModal('ingredient')}} onOpen={(i:Ingredient)=>{setEditingIngredient(i);setModal('ingredient')}}/>}{section==='carte-associations'&&<CarteAssociations ingredients={ingredients} units={units} onSaved={refreshAll}/>} {section==='rch'&&<RchConsumptions ingredients={ingredients} units={units} onCreated={refreshAll}/>} {section==='reports'&&<Reports events={events} recipes={recipes} catalogIngredients={ingredients}/>}</div></main>{modal==='event'&&<EventModal clients={clients} event={editingEvent} onClose={()=>{setModal(null);setEditingEvent(null)}} onSaved={refreshAll}/>} {modal==='client'&&<ClientModal client={editingClient} onClose={()=>{setModal(null);setEditingClient(null)}} onSaved={refreshAll}/>} {modal==='ingredient'&&<IngredientModal ingredient={editingIngredient} units={units} onClose={()=>{setModal(null);setEditingIngredient(null)}} onSaved={refreshAll}/>} {modal==='recipe'&&<RecipeModal recipe={editingRecipe} collection={newRecipeCollection} ingredients={ingredients} units={units} onClose={()=>{setModal(null);setEditingRecipe(null)}} onSaved={refreshAll}/>}</div>
}

function SetupScreen(){return <div className="setup"><div className="setupCard"><div className="brandMark big">22</div><h1>Orders NG</h1><p>Il frontend è pronto. Mancano soltanto le due variabili Supabase.</p><code>NEXT_PUBLIC_SUPABASE_URL</code><code>NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY</code><p className="muted">Inseriscile su Vercel nelle Environment Variables oppure nel file .env.local per l'uso sul Mac.</p></div></div>}
function Login({email,password,setEmail,setPassword,submit,message}:any){return <div className="loginWrap"><form className="loginCard" onSubmit={submit}><div className="brandMark big">22</div><div><span className="eyebrow">OFFICINA22</span><h1>Orders NG</h1><p>Accedi al gestionale.</p></div><label>Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required autoComplete="email"/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password"/></label>{message&&<div className={message==='Accesso in corso…'?'authInfoBox':'errorBox'}>{message}</div>}<button className="primary full" type="submit">Accedi</button></form></div>}
function Dashboard({upcoming,confirmed,waiting,monthEvents,onOpen,onSection}:any){return <><div className="hero"><div><h2 className="heroQuote">If you can’t measure it, you can’t improve it.</h2><p className="heroAuthor">Peter Drucker</p></div><div className="heroBadge"><CalendarDays/><span>Oggi</span><strong>{new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'long'}).format(new Date())}</strong></div></div><div className="stats"><Stat label="Eventi questo mese" value={monthEvents}/><Stat label="Confermati futuri" value={confirmed}/><Stat label="Preventivi da seguire" value={waiting}/><Stat label="Prossimi eventi" value={upcoming.length}/></div><div className="grid2"><section className="panel"><div className="panelHead"><div><span className="eyebrow">AGENDA</span><h3>Prossimi eventi</h3></div><button className="textButton" onClick={()=>onSection('events')}>Vedi tutti</button></div>{upcoming.length===0?<Empty text="Nessun evento futuro."/>:<div className="eventList">{upcoming.map((e:EventRow)=><button className="eventRow" key={e.id} onClick={()=>onOpen(e)}><div className="dateTile"><strong>{new Date(e.event_date+'T12:00:00').getDate()}</strong><span>{new Intl.DateTimeFormat('it-IT',{month:'short'}).format(new Date(e.event_date+'T12:00:00'))}</span></div><div className="eventInfo"><strong>{e.title||nameOfClient(e.client)}</strong><span>{nameOfClient(e.client)} · {e.service||'servizio da definire'}</span></div><span className={'status s-'+e.status}>{statusLabel[e.status]||e.status}</span></button>)}</div>}</section><section className="panel"><div className="panelHead"><div><span className="eyebrow">FLUSSO</span><h3>Orders NG</h3></div></div><div className="flow"><Flow n="01" title="Evento" text="Cliente, data, ospiti e servizio"/><Flow n="02" title="Menu" text="Portate collegate alle ricette"/><Flow n="03" title="Food cost" text="Costo reale e prezzo suggerito"/><Flow n="04" title="Preventivo" text="PDF cliente versionato"/><Flow n="05" title="Produzione" text="Quantità aggregate per la cucina"/></div></section></div></>}
function Stat({label,value}:{label:string,value:number}){return <div className="stat"><span>{label}</span><strong>{value}</strong></div>}
function Flow({n,title,text}:{n:string,title:string,text:string}){return <div className="flowRow"><span>{n}</span><div><strong>{title}</strong><p>{text}</p></div></div>}
function Empty({text}:{text:string}){return <div className="empty">{text}</div>}
function SearchBar({value,setValue,placeholder,action}:any){return <div className="toolbar"><div className="search"><Search size={18}/><input value={value} onChange={e=>setValue(e.target.value)} placeholder={placeholder}/></div>{action}</div>}
function Events({events,query,setQuery,onOpen,onNew}:any){const q=query.toLowerCase();const list=events.filter((e:EventRow)=>[e.title,nameOfClient(e.client),e.event_type,e.status].join(' ').toLowerCase().includes(q));return <><SearchBar value={query} setValue={setQuery} placeholder="Cerca evento, cliente, stato…" action={<button className="primary" onClick={onNew}><Plus size={18}/> Nuovo evento</button>}/><section className="panel tablePanel"><div className="responsiveTable"><table><thead><tr><th>N.</th><th>Data</th><th>Cliente / Evento</th><th>Servizio</th><th>Ospiti</th><th>Stato</th><th>Prezzo</th></tr></thead><tbody>{list.map((e:EventRow)=><tr key={e.id} onClick={()=>onOpen(e)}><td>#{e.event_number}</td><td>{new Intl.DateTimeFormat('it-IT').format(new Date(e.event_date+'T12:00:00'))}</td><td><strong>{e.title||nameOfClient(e.client)}</strong><small>{nameOfClient(e.client)}</small></td><td>{e.service||'—'}</td><td>{e.adults+e.children+e.baby}</td><td><span className={'status s-'+e.status}>{statusLabel[e.status]||e.status}</span></td><td>{e.price_per_adult?euro(e.price_per_adult):'—'}</td></tr>)}</tbody></table></div>{list.length===0&&<Empty text="Nessun evento trovato."/>}</section></>}
function Clients({clients,query,setQuery,onNew,onOpen}:any){const q=query.toLowerCase();const list=clients.filter((c:Client)=>[c.client_number,nameOfClient(c),c.phone,c.email,c.city].join(' ').toLowerCase().includes(q));return <><SearchBar value={query} setValue={setQuery} placeholder="Cerca cliente o ID…" action={<button className="secondary" onClick={onNew}><Plus size={17}/> Nuovo cliente</button>}/><div className="cards">{list.map((c:Client)=><article className="clientCard" key={c.id} onClick={()=>onOpen(c)} role="button" tabIndex={0}><div className="avatar"><ContactRound/></div><div><span className="eyebrow">{c.client_number?`CLIENTE #${c.client_number}`:c.customer_type}</span><h3>{nameOfClient(c)}</h3><p>{c.phone||'Nessun telefono'}</p><p>{c.email||'Nessuna email'}</p>{c.city&&<small>{c.city}</small>}</div><Pencil size={16}/></article>)}</div>{list.length===0&&<Empty text="Nessun cliente trovato."/>}</>}
function RecipeCollectionTabs({value,onChange,recipes}:{value:RecipeCollection;onChange:(value:RecipeCollection)=>void;recipes:Recipe[]}){return <div className="recipeCollectionTabs" aria-label="Ricettario">{([{id:'banquets',label:'Banchetti'},{id:'a_la_carte',label:'À la carte'}] as const).map(item=><button type="button" key={item.id} aria-pressed={value===item.id} className={value===item.id?'recipeCollectionTab active':'recipeCollectionTab'} onClick={()=>onChange(item.id)}><ChefHat size={22}/><span><strong>{item.label}</strong><small>{recipes.filter(r=>(r.recipe_collection||'banquets')===item.id).length} ricette</small></span></button>)}</div>}

function Recipes({recipes,onNew,onOpen,onAssociations}:any){const [collection,setCollection]=useState<RecipeCollection>('banquets');const [category,setCategory]=useState<string>('Tutte');const [recipeQuery,setRecipeQuery]=useState('');const q=recipeQuery.trim().toLowerCase();const list=recipes.filter((r:Recipe)=>{const normalized=normalizeRecipeCategory(r.category);return (r.recipe_collection||'banquets')===collection&&(category==='Tutte'||normalized===category)&&(!q||[r.name,normalized||r.category].join(' ').toLowerCase().includes(q))});return <><RecipeCollectionTabs value={collection} onChange={setCollection} recipes={recipes}/>{collection==='a_la_carte'&&<button className="secondary" style={{marginBottom:16}} onClick={onAssociations}>Associazioni ingredienti</button>}<div className="toolbar recipesToolbar"><div className="search recipeSearch"><Search size={18}/><input value={recipeQuery} onChange={e=>setRecipeQuery(e.target.value)} placeholder="Cerca ricetta…"/></div><button className="secondary" onClick={()=>onNew(collection)}><Plus size={17}/> Nuova ricetta</button></div><div className="recipeFilters"><div className="categoryTabs"><button className={category==='Tutte'?'categoryTab active':'categoryTab'} onClick={()=>setCategory('Tutte')}>Tutte</button>{RECIPE_CATEGORIES.map(c=><button key={c} className={category===c?'categoryTab active':'categoryTab'} onClick={()=>setCategory(c)}>{c}</button>)}</div></div><div className="recipeCards">{list.map((r:Recipe)=>{const total=recipeCost(r);const suggested=suggestedPrice(r);const categoryLabel=normalizeRecipeCategory(r.category)||r.category||'Senza categoria';return <button className="recipeCard" key={r.id} onClick={()=>onOpen(r)}><div className="recipeCardTop"><div className="iconDisc"><ChefHat/></div><div><span className="eyebrow">{r.recipe_number?`RICETTA #${r.recipe_number} · `:''}{categoryLabel}</span><h3>{r.name}</h3><p>{(r.recipe_ingredients||[]).length} ingredienti</p></div><Pencil size={17}/></div><div className="recipeMetrics"><div><span>Costo ricetta</span><strong>{euro(total)}</strong></div><div><span>Prezzo consigliato</span><strong className="accentText">{suggested?euro(suggested):'—'}</strong></div></div></button>})}</div>{list.length===0&&<Empty text="Nessuna ricetta trovata in questa categoria."/>}</>}
function Ingredients({ingredients,onNew,onOpen}:any){const [ingredientQuery,setIngredientQuery]=useState('');const q=ingredientQuery.trim().toLowerCase();const list=ingredients.filter((i:Ingredient)=>!q||[i.ingredient_number,i.name,i.category,i.unit?.code].join(' ').toLowerCase().includes(q));return <><div className="toolbar ingredientsToolbar"><div className="search recipeSearch"><Search size={18}/><input value={ingredientQuery} onChange={e=>setIngredientQuery(e.target.value)} placeholder="Cerca ingrediente…"/></div><button className="secondary" onClick={onNew}><Plus size={17}/> Nuovo ingrediente</button></div><section className="panel tablePanel"><div className="responsiveTable"><table><thead><tr><th>ID</th><th>Ingrediente</th><th>Categoria</th><th>Unità</th><th>Prezzo corrente</th><th>Quotazione</th><th>Stato</th><th></th></tr></thead><tbody>{list.map((i:Ingredient)=><tr key={i.id} onClick={()=>onOpen(i)}><td>{i.ingredient_number?`#${i.ingredient_number}`:'—'}</td><td><strong>{i.name}</strong></td><td>{i.category||'—'}</td><td>{i.unit?.code||'—'}</td><td>{euro(i.current_price)}{i.unit?.code?` / ${i.unit.code}`:''}</td><td><strong>{quotationLabel(i.current_price_date)}</strong></td><td>{i.active?'Attivo':'Disattivato'}</td><td><Pencil size={16}/></td></tr>)}</tbody></table></div>{ingredients.length===0&&<Empty text="Nessun ingrediente registrato."/>}</section></>}
function KitchenHome({events,recipes,loading,logout}:{events:EventRow[];recipes:Recipe[];loading:boolean;logout:()=>Promise<void>}){
 const [selected,setSelected]=useState<string[]>([])
 const [query,setQuery]=useState('')
 const [kitchenSection,setKitchenSection]=useState<'events'|'recipes'>('events')
 const [recipeQuery,setRecipeQuery]=useState('')
 const [collection,setCollection]=useState<RecipeCollection>('banquets')
 const [recipeCategory,setRecipeCategory]=useState('Tutte')
 const [selectedRecipe,setSelectedRecipe]=useState<Recipe|null>(null)
 const q=query.trim().toLowerCase()
 const list=events.filter(e=>e.status!=='annullato'&&(!q||[e.event_number,e.title,nameOfClient(e.client),e.event_date,e.service].join(' ').toLowerCase().includes(q)))
 const rq=recipeQuery.trim().toLowerCase()
 const recipeList=recipes.filter(r=>{const cat=normalizeRecipeCategory(r.category)||r.category||'Senza categoria';return (r.recipe_collection||'banquets')===collection&&(recipeCategory==='Tutte'||cat===recipeCategory)&&(!rq||[r.name,cat,r.procedure,r.notes].join(' ').toLowerCase().includes(rq))})
 function toggle(id:string){setSelected(v=>v.includes(id)?v.filter(x=>x!==id):[...v,id])}
 function allVisible(){const ids=list.map(e=>e.id);setSelected(v=>ids.every(id=>v.includes(id))?v.filter(id=>!ids.includes(id)):Array.from(new Set([...v,...ids])))}
 return <div className="appShell kitchenShell"><aside className="sidebar"><div className="brand"><div className="brandMark">22</div><div><strong>Orders NG</strong><span>Cucina</span></div></div><nav><button className={kitchenSection==='events'?'navItem active':'navItem'} onClick={()=>setKitchenSection('events')}><CalendarDays size={19}/><span>Eventi</span></button><button className={kitchenSection==='recipes'?'navItem active':'navItem'} onClick={()=>setKitchenSection('recipes')}><ChefHat size={19}/><span>Ricettario</span></button></nav><div className="sidebarBottom"><button className="navItem" onClick={logout}><LogOut size={19}/><span>Esci</span></button></div></aside><main className="main"><header className="topbar"><div><span className="eyebrow">ORDERS NEXTGEN · CUCINA</span><h1>{kitchenSection==='events'?'Eventi':'Ricettario'}</h1></div></header><div className="content">{loading&&<div className="loadingLine"/>}{kitchenSection==='events'?<><div className="kitchenIntro"><div><span className="eyebrow kitchenProductionLabel">PRODUZIONE CUCINA</span><h2>Seleziona gli eventi da preparare</h2><p>Puoi scegliere liberamente uno o più eventi e ottenere un unico report di produzione.</p></div><div className="kitchenSelectedCount"><strong>{selected.length}</strong><span>selezionati</span></div></div><SearchBar value={query} setValue={setQuery} placeholder="Cerca evento, cliente o data…" action={<button className="secondary" onClick={allVisible}>{list.length>0&&list.every(e=>selected.includes(e.id))?'Deseleziona tutti':'Seleziona tutti'}</button>}/><section className="panel tablePanel kitchenEventsPanel"><div className="responsiveTable"><table><thead><tr><th className="kitchenCheckCol"></th><th>N.</th><th>Data</th><th>Cliente / Evento</th><th>Servizio</th><th>Adulti</th><th>Baby</th></tr></thead><tbody>{list.map(e=><tr key={e.id} className={selected.includes(e.id)?'kitchenEventSelected':''} onClick={()=>toggle(e.id)}><td className="kitchenCheckCol"><input type="checkbox" checked={selected.includes(e.id)} onChange={()=>toggle(e.id)} onClick={ev=>ev.stopPropagation()}/></td><td>#{e.event_number}</td><td>{new Intl.DateTimeFormat('it-IT').format(new Date(e.event_date+'T12:00:00'))}</td><td><strong>{e.title||nameOfClient(e.client)}</strong><small>{nameOfClient(e.client)}</small></td><td>{e.service||'—'}</td><td>{e.adults}</td><td>{e.baby}</td></tr>)}</tbody></table></div>{list.length===0&&<Empty text="Nessun evento trovato."/>}</section>{selected.length>0?<Reports events={events} recipes={recipes} selectedEventIds={selected} kitchen/>:<div className="kitchenReportEmpty"><ClipboardList size={28}/><strong>Seleziona almeno un evento</strong><span>Qui compariranno i report Piatti e Ingredienti raggruppati.</span></div>}</>:<><RecipeCollectionTabs value={collection} onChange={setCollection} recipes={recipes}/><div className="toolbar recipesToolbar"><div className="search recipeSearch"><Search size={18}/><input value={recipeQuery} onChange={e=>setRecipeQuery(e.target.value)} placeholder="Cerca ricetta…"/></div></div><div className="recipeFilters"><div className="categoryTabs"><button className={recipeCategory==='Tutte'?'categoryTab active':'categoryTab'} onClick={()=>setRecipeCategory('Tutte')}>Tutte</button>{RECIPE_CATEGORIES.map(cat=><button key={cat} className={recipeCategory===cat?'categoryTab active':'categoryTab'} onClick={()=>setRecipeCategory(cat)}>{cat}</button>)}</div></div><div className="recipeCards">{recipeList.map(r=>{const total=recipeCost(r);const suggested=suggestedPrice(r);const categoryLabel=normalizeRecipeCategory(r.category)||r.category||'Senza categoria';return <button className="recipeCard" key={r.id} onClick={()=>setSelectedRecipe(r)}><div className="recipeCardTop"><div className="iconDisc"><ChefHat/></div><div><span className="eyebrow">{r.recipe_number?`RICETTA #${r.recipe_number} · `:''}{categoryLabel}</span><h3>{r.name}</h3><p>{(r.recipe_ingredients||[]).length} ingredienti</p></div></div><div className="recipeMetrics"><div><span>Costo ricetta</span><strong>{euro(total)}</strong></div><div><span>Prezzo consigliato</span><strong className="accentText">{suggested?euro(suggested):'—'}</strong></div></div></button>})}</div>{recipeList.length===0&&<Empty text="Nessuna ricetta trovata."/>}</>}</div>{selectedRecipe&&<KitchenRecipeModal recipe={selectedRecipe} onClose={()=>setSelectedRecipe(null)}/>}</main></div>
}

function KitchenRecipeModal({recipe,onClose}:{recipe:Recipe;onClose:()=>void}){const categoryLabel=normalizeRecipeCategory(recipe.category)||recipe.category||'Senza categoria';return <Modal title={recipe.name} onClose={onClose} wide><div className="kitchenRecipeReadOnly"><div className="recipeReadOnlyMeta"><span className="eyebrow">{recipe.recipe_number?`RICETTA #${recipe.recipe_number} · `:''}{categoryLabel}</span><strong>{(recipe.recipe_ingredients||[]).length} ingredienti</strong></div><section className="compositionBox"><div className="compositionHead"><div><span className="eyebrow">RICETTA E COMPOSIZIONE</span><h3>Ingredienti necessari</h3></div></div><div className="ingredientImpactList">{(recipe.recipe_ingredients||[]).map((line:any,idx:number)=><div className="ingredientImpactRecipe" key={line.id||idx}><div><strong>{line.ingredient?.name||'Ingrediente'}</strong><small>{Number(line.quantity||0).toLocaleString('it-IT',{maximumFractionDigits:3})} {line.unit?.code||line.ingredient?.unit?.code||''}</small></div></div>)}</div></section>{recipe.procedure&&<section className="recipeReadOnlySection"><span className="eyebrow">PROCEDIMENTO</span><p>{recipe.procedure}</p></section>}{recipe.notes&&<section className="recipeReadOnlySection"><span className="eyebrow">NOTE</span><p>{recipe.notes}</p></section>}</div></Modal>}

const reportCategory=(category?:string|null)=>{const c=(category||'').trim();const map:Record<string,string>={'Antipasti':'Antipasto','Primi':'Primo','Secondi':'Secondo','Contorni':'Contorno','Dessert':'Dessert','Dolci':'Dolce'};return map[c]||c.replace(/i$/,'o')};function Reports({events,recipes,selectedEventIds,kitchen=false,catalogIngredients=[]}:{events:EventRow[];recipes:Recipe[];selectedEventIds?:string[];kitchen?:boolean;catalogIngredients?:Ingredient[]}){const now=new Date();const today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;const [from,setFrom]=useState(today);const [to,setTo]=useState(today);const [view,setView]=useState<'dishes'|'ingredients'|'shopping'>('dishes');const [menuItems,setMenuItems]=useState<any[]>([]);const [rchReports,setRchReports]=useState<RchImport[]>([]);const [rchReportId,setRchReportId]=useState('');const [includeBanquets,setIncludeBanquets]=useState(true);useEffect(()=>{if(!kitchen)loadRchImports().then(setRchReports).catch(e=>setError(e.message))},[kitchen]);const [busy,setBusy]=useState(false);const [exporting,setExporting]=useState(false);const [error,setError]=useState('');useEffect(()=>{if(!supabase)return;const selected=events.filter(e=>e.status!=='annullato'&&(selectedEventIds?selectedEventIds.includes(e.id):(e.event_date>=from&&e.event_date<=to)));if(!selected.length){setMenuItems([]);return}let cancelled=false;(async()=>{setBusy(true);setError('');const ids=selected.map(e=>e.id);const menus=await supabase.from('event_menus').select('id,event_id,name').in('event_id',ids).eq('active',true);if(menus.error){if(!cancelled)setError(menus.error.message);setBusy(false);return}const menuRows=menus.data||[];if(!menuRows.length){if(!cancelled)setMenuItems([]);setBusy(false);return}const items=await supabase.from('event_menu_items').select('menu_id,recipe_id,display_name,portions').in('menu_id',menuRows.map((m:any)=>m.id));if(items.error){if(!cancelled)setError(items.error.message)}else if(!cancelled){const menuEvent=new Map(menuRows.map((m:any)=>[m.id,m.event_id]));const menuName=new Map(menuRows.map((m:any)=>[m.id,m.name]));setMenuItems((items.data||[]).map((x:any)=>({...x,event_id:menuEvent.get(x.menu_id),menu_name:menuName.get(x.menu_id)})))}setBusy(false)})();return()=>{cancelled=true}},[events,from,to,selectedEventIds?.join('|')]);const selectedEvents=events.filter(e=>e.status!=='annullato'&&(selectedEventIds?selectedEventIds.includes(e.id):(e.event_date>=from&&e.event_date<=to)));const totalBaby=selectedEvents.reduce((sum,e)=>sum+Math.max(0,Number(e.baby||0)),0);const totalCovers=selectedEvents.reduce((sum,e)=>sum+Math.max(0,Number(e.adults||0))+Math.max(0,Number(e.children||0))+Math.max(0,Number(e.baby||0)),0);const dedicatedEvents=selectedEvents.filter(hasDedicatedMenus);const dedicatedTotals=dedicatedMenuTotals(dedicatedEvents);const dedicatedExportRows=()=>dedicatedEvents.map(e=>({Evento:`#${e.event_number}`,Data:e.event_date.split('-').reverse().join('/'),Cliente:e.title||nameOfClient(e.client),Servizio:e.service||'—',...Object.fromEntries(DEDICATED_MENU_FIELDS.map(({key,label})=>[label,dedicatedMenuCount(e,key)]))}));const eventMap=new Map(selectedEvents.map(e=>[e.id,e]));const recipeMap=new Map(recipes.map(r=>[r.id,r]));const dishMap=new Map<string,{id:string;name:string;category:string;quantity:number}>();for(const item of menuItems){const ev=eventMap.get(item.event_id);if(!ev)continue;const r=recipeMap.get(item.recipe_id);const savedPortions=Number(item.portions||0);const isBaby=item.menu_name==='Menu baby';const qty=savedPortions>0&&(isBaby||savedPortions>1)?savedPortions:(isBaby?Math.max(0,Number(ev.baby||0)):Math.max(0,Number(ev.adults||0)+Number(ev.children||0)));const key=item.recipe_id||item.display_name;if(!dishMap.has(key))dishMap.set(key,{id:key,name:r?.name||item.display_name||'Portata',category:normalizeRecipeCategory(r?.category)||r?.category||'—',quantity:0});dishMap.get(key)!.quantity+=qty}const courseOrder=(category:string)=>{const index=RECIPE_CATEGORIES.indexOf(normalizeRecipeCategory(category) as typeof RECIPE_CATEGORIES[number]);return index<0?RECIPE_CATEGORIES.length:index};const dishes=Array.from(dishMap.values()).sort((a,b)=>courseOrder(a.category)-courseOrder(b.category)||a.name.localeCompare(b.name,'it'));type Agg={id:string;name:string;family:string;quantity:number;unit:string};const ingredientMap=new Map<string,Agg>();for(const dish of dishes){const r=recipeMap.get(dish.id);if(!r)continue;const portions=Math.max(1,Number(r.standard_portions||1));for(const line of r.recipe_ingredients||[]){const ing=line.ingredient; if(!ing)continue;const code=line.unit?.code||ing.unit?.code||'';const fam=family[code]||code||'other';const baseCode=fam==='mass'?'g':fam==='volume'?'ml':code;const baseQty=baseCode?convertQuantity(Number(line.quantity||0),code,baseCode):Number(line.quantity||0);const key=ing.id+'|'+fam;const add=baseQty*(dish.quantity/portions);if(!ingredientMap.has(key))ingredientMap.set(key,{id:ing.id,name:ing.name,family:fam,quantity:0,unit:baseCode});ingredientMap.get(key)!.quantity+=add}}const ingredientsAgg=Array.from(ingredientMap.values()).map(x=>{if(x.family==='mass'&&x.quantity>=1000)return{...x,quantity:x.quantity/1000,unit:'kg'};if(x.family==='volume'&&x.quantity>=1000)return{...x,quantity:x.quantity/1000,unit:'l'};return x}).sort((a,b)=>a.name.localeCompare(b.name));const selectedRch=rchReports.find(r=>r.id===rchReportId);const shoppingMap=new Map<string,{id:string;name:string;unit:string;carte:number;banquets:number;quantity:number}>();if(includeBanquets)for(const i of ingredientsAgg){const unit=i.family==='mass'?'kg':i.family==='volume'?'l':i.unit;const quantity=convertQuantity(i.quantity,i.unit,unit);shoppingMap.set(i.id+'|'+unit,{id:i.id,name:i.name,unit,carte:0,banquets:quantity,quantity})}if(selectedRch)for(const i of rchConsumption(selectedRch)){const key=i.id+'|'+i.unit;const name=catalogIngredients.find(x=>x.id===i.id)?.name||recipes.flatMap(r=>r.recipe_ingredients||[]).find(l=>l.ingredient_id===i.id)?.ingredient?.name||i.name;if(!shoppingMap.has(key))shoppingMap.set(key,{id:i.id,name,unit:i.unit,carte:0,banquets:0,quantity:0});const current=shoppingMap.get(key)!;current.carte+=i.quantity;current.quantity+=i.quantity}const shoppingRows=Array.from(shoppingMap.values()).sort((a,b)=>a.name.localeCompare(b.name,'it'));const totalRawMaterialsKg=Math.round(dishes.reduce((sum,dish)=>{const r=recipeMap.get(dish.id);if(!r)return sum;const portions=Math.max(1,Number(r.standard_portions||1));for(const line of r.recipe_ingredients||[]){const unit=String(line.unit?.code||line.ingredient?.unit?.code||'').trim().toLowerCase();const qty=Number(line.quantity||0)*(dish.quantity/portions);if(unit==='kg')sum+=qty;else if(unit==='g'||unit==='gr')sum+=qty/1000}return sum},0));const fmt=(n:number)=>new Intl.NumberFormat('it-IT',{maximumFractionDigits:3}).format(n);const fileRange=from.replaceAll('-','')+'-'+to.replaceAll('-','');const dishExportRows=()=>dishes.flatMap(d=>{const r=recipeMap.get(d.id);const portions=Math.max(1,Number(r?.standard_portions||1));return (r?.recipe_ingredients||[]).map((line:any,index:number)=>{const ing=line.ingredient;const unit=line.unit?.code||ing?.unit?.code||'';const saggio=Number(line.quantity||0)/portions;return {Piatto:index===0?d.name:'',Categoria:index===0?d.category:'',QT:index===0?d.quantity:'',Ingrediente:ing?.name||'Ingrediente',Saggio:saggio,UM:unit||'',Totale:saggio*d.quantity}})});async function exportExcel(){const XLSX=await import('xlsx');const rows=view==='shopping'?shoppingRows.map(i=>({Ingrediente:i.name,UM:i.unit,'Reintegro à la carte':i.carte,Banchetti:i.banquets,'Totale acquisto':i.quantity})):view==='dishes'?dishExportRows():ingredientsAgg.map(i=>({Ingrediente:i.name,'Quantità totale':i.quantity,UM:i.unit||''}));const ws=XLSX.utils.aoa_to_sheet([['Coperti totali',totalCovers],['Baby',totalBaby],...(view==='shopping'?[[selectedRch?`Consumo RCH dal ${selectedRch.period_from} al ${selectedRch.period_to}`:'Nessun consumo RCH',includeBanquets?`Banchetti dal ${from} al ${to}`:'Senza banchetti']]:[[]])]);XLSX.utils.sheet_add_json(ws,rows,{origin:'A4'});ws['!cols']=view==='dishes'?[{wch:28},{wch:18},{wch:10},{wch:34},{wch:12},{wch:10},{wch:14}]:[{wch:36},{wch:18},{wch:10}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,view==='shopping'?'Lista acquisti':view==='dishes'?'Piatti':'Ingredienti');if(dedicatedEvents.length&&(view!=='shopping'||includeBanquets)){const dedicatedSheet=XLSX.utils.json_to_sheet([...dedicatedExportRows(),{Evento:'Totale',...Object.fromEntries(DEDICATED_MENU_FIELDS.map(({key,label})=>[label,dedicatedTotals[key]]))}]);dedicatedSheet['!cols']=[{wch:10},{wch:14},{wch:34},{wch:12},...DEDICATED_MENU_FIELDS.map(()=>({wch:16}))];XLSX.utils.book_append_sheet(wb,dedicatedSheet,'Menu dedicati')}XLSX.writeFile(wb,`fabbisogno_${view==='shopping'?'acquisti':view==='dishes'?'piatti':'ingredienti'}_${fileRange}.xlsx`)}async function exportPdf(){setExporting(true);setError('');try{const panel=document.querySelector<HTMLElement>('.productionReportPanel');if(!panel)throw new Error('Report non disponibile.');const {exportReportPdf}=await import('@/lib/report-pdf');await exportReportPdf(panel,`fabbisogno_${view==='shopping'?'acquisti':view==='dishes'?'piatti':'ingredienti'}_${fileRange}.pdf`)}catch(error){setError(error instanceof Error?error.message:'Impossibile esportare il PDF.')}finally{setExporting(false)}};function printReport(){window.print()}return <>{!kitchen&&<div className="hero compact"><div><span className="eyebrow">PRODUZIONE CUCINA</span><h2>Fabbisogno per intervallo</h2><p>Piatti e ingredienti calcolati dai menu degli eventi e aggregati con il consumo del menu à la carte.</p></div></div>}<div className={kitchen?"toolbar kitchenReportToolbar":"toolbar"}>{!kitchen&&<div className="reportDates"><label>Report dal<input type="date" value={from} onChange={e=>setFrom(e.target.value)}/></label><label>al<input type="date" value={to} min={from} onChange={e=>setTo(e.target.value)}/></label></div>}<div className="categoryTabs"><button className={view==='dishes'?'categoryTab active':'categoryTab'} onClick={()=>setView('dishes')}>Piatti</button><button className={view==='ingredients'?'categoryTab active':'categoryTab'} onClick={()=>setView('ingredients')}>Ingredienti raggruppati</button>{!kitchen&&<button className={view==='shopping'?'categoryTab active':'categoryTab'} onClick={()=>setView('shopping')}>Aggregatore</button>}</div></div>{view==='shopping'&&<section className="panel rchReportControls"><label>Reintegro à la carte<select value={rchReportId} onChange={e=>setRchReportId(e.target.value)}><option value="">Nessun resoconto RCH</option>{rchReports.map(r=><option key={r.id} value={r.id}>{r.period_from.split('-').reverse().join('/')} — {r.period_to.split('-').reverse().join('/')} · {r.filename}</option>)}</select></label><label><span><input type="checkbox" checked={includeBanquets} onChange={e=>setIncludeBanquets(e.target.checked)}/> Aggiungi banchetti nell’intervallo selezionato</span></label></section>}{error&&<div className="errorBox">{error}</div>}<div className="stats reportStats"><Stat label={kitchen?'Eventi selezionati':"Eventi nell'intervallo"} value={selectedEvents.length}/><Stat label="Piatti diversi" value={dishes.length}/><Stat label="Ingredienti diversi" value={view==='shopping'?shoppingRows.length:ingredientsAgg.length}/><Stat label="Materie prime in kg" value={view==='shopping'?Math.round(shoppingRows.filter(r=>r.unit==='kg').reduce((s,r)=>s+r.quantity,0)):totalRawMaterialsKg}/></div><section className="panel tablePanel productionReportPanel"><div className="panelHead"><div><span className="eyebrow">{view==='dishes'?'PIATTI NECESSARI':'LISTA AGGREGATA'}</span><h3>{view==='shopping'?'Lista acquisti':view==='dishes'?'Portate e ingredienti':'Fabbisogno ingredienti'}</h3><p className="reportPeriod">{kitchen?`Report su ${selectedEvents.length} eventi selezionati`:`Report dal ${from.split('-').reverse().join('/')} al ${to.split('-').reverse().join('/')}`}</p>{view==='shopping'&&<p className="reportPeriod">{selectedRch?`Reintegro à la carte dal ${selectedRch.period_from.split('-').reverse().join('/')} al ${selectedRch.period_to.split('-').reverse().join('/')}`:'Senza reintegro à la carte'} · {includeBanquets?'Banchetti inclusi':'Banchetti esclusi'}</p>}<p className="reportPeriod reportGuestTotals">Coperti totali: {fmt(totalCovers)} · Baby: {fmt(totalBaby)}</p></div><div className="reportExportActions">{!kitchen&&<><button className="secondary" onClick={exportExcel} disabled={busy}>Esporta Excel</button><button className="secondary" onClick={exportPdf} disabled={busy||exporting}>{exporting?'Generazione PDF…':'Esporta PDF'}</button></>}<button className="secondary" onClick={printReport} disabled={busy||(view==='shopping'?shoppingRows.length===0:selectedEvents.length===0)}>Stampa</button></div></div>{busy?<div className="empty">Calcolo in corso…</div>:view==='shopping'?<div className="responsiveTable"><table><thead><tr><th>Ingrediente</th><th>UM</th><th>Reintegro à la carte</th><th>Banchetti</th><th>Totale acquisto</th></tr></thead><tbody>{shoppingRows.map(i=><tr key={i.id+'|'+i.unit}><td><strong>{i.name}</strong></td><td>{i.unit}</td><td>{fmt(i.carte)}</td><td>{fmt(i.banquets)}</td><td><strong>{fmt(i.quantity)}</strong></td></tr>)}</tbody></table>{!shoppingRows.length&&<Empty text="Seleziona un resoconto RCH o un intervallo con banchetti."/>}</div>:view==='dishes'?<div className="responsiveTable"><table className="productionTable"><thead><tr><th>QT</th><th>Ingrediente</th><th>Saggio</th><th>UM</th><th>Totale</th></tr></thead><tbody>{dishes.map(d=>{const r=recipeMap.get(d.id);const portions=Math.max(1,Number(r?.standard_portions||1));const lines=r?.recipe_ingredients||[];return <Fragment key={d.id}><tr className="productionDishRow"><td colSpan={5}><strong>{d.name}</strong><span className="productionCategory"><span>{reportCategory(d.category)}</span><span>Porzioni {fmt(d.quantity)}</span></span></td></tr>{lines.map((line:any,idx:number)=>{const ing=line.ingredient;const unit=line.unit?.code||ing?.unit?.code||'';const recipeQty=Number(line.quantity||0);const saggio=recipeQty/portions;const total=saggio*d.quantity;return <tr key={d.id+'-'+(ing?.id||idx)}><td></td><td><strong>{ing?.name||'Ingrediente'}</strong></td><td>{fmt(saggio)}</td><td>{unit||'—'}</td><td><strong>{fmt(total)}</strong></td></tr>})}</Fragment>})}</tbody></table>{dishes.length===0&&<Empty text="Nessun piatto trovato nell'intervallo selezionato."/>}</div>:<div className="responsiveTable"><table><thead><tr><th>Ingrediente</th><th>UM</th><th>Quantità totale</th></tr></thead><tbody>{ingredientsAgg.map(i=><tr key={i.id+'-'+i.family}><td><strong>{i.name}</strong></td><td>{i.unit||'—'}</td><td><strong>{fmt(i.quantity)}</strong></td></tr>)}</tbody></table>{ingredientsAgg.length===0&&<Empty text="Nessun ingrediente da aggregare nell'intervallo selezionato."/>}</div>}{dedicatedEvents.length>0&&(view!=='shopping'||includeBanquets)&&<section className="dedicatedReportSummary" aria-label="Menu dedicati"><h4>MENU DEDICATI</h4><div className="responsiveTable"><table className="dedicatedReportTable"><thead><tr><th>Evento / Cliente</th><th>Data</th><th>Servizio</th>{DEDICATED_MENU_FIELDS.map(({key,label})=><th key={key}>{label}</th>)}</tr></thead><tbody>{dedicatedEvents.map(e=><tr key={e.id}><td><strong>#{e.event_number} · {e.title||nameOfClient(e.client)}</strong></td><td>{e.event_date.split('-').reverse().join('/')}</td><td>{e.service||'—'}</td>{DEDICATED_MENU_FIELDS.map(({key})=><td key={key}>{dedicatedMenuCount(e,key)}</td>)}</tr>)}</tbody><tfoot><tr><th colSpan={3}>Totale</th>{DEDICATED_MENU_FIELDS.map(({key})=><th key={key}>{dedicatedTotals[key]}</th>)}</tr></tfoot></table></div></section>}</section></>}
