function RecipeModal({recipe,collection,ingredients,units,onClose,onSaved}:{recipe:Recipe|null;collection:RecipeCollection;ingredients:Ingredient[];units:Unit[];onClose:()=>void;onSaved:()=>Promise<void>}){const normalizedInitialCategory=normalizeRecipeCategory(recipe?.category)||'';const [f,setF]=useState({name:recipe?.name||'',category:normalizedInitialCategory,target_food_cost_percent:recipe?.target_food_cost_percent?.toString()||'30',manual_sale_price:recipe?.manual_sale_price?.toString()||'',procedure:recipe?.procedure||'',notes:recipe?.notes||''});const initialLines=(recipe?.recipe_ingredients||[]).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0)).map(l=>({ingredient_id:l.ingredient_id,quantity:String(l.quantity),unit_id:l.unit_id||l.ingredient?.unit_id||''}));const [lines,setLines]=useState<{ingredient_id:string;quantity:string;unit_id:string}[]>(initialLines);const [saving,setSaving]=useState(false);const hydratedLines=useMemo(()=>lines.map((l,idx)=>{const ing=ingredients.find(i=>i.id===l.ingredient_id)||null;const unit=units.find(u=>u.id===l.unit_id)||ing?.unit||null;return {ingredient_id:l.ingredient_id,quantity:Number(l.quantity||0),unit_id:l.unit_id||null,sort_order:idx,ingredient:ing,unit}}),[lines,ingredients,units]);const total=hydratedLines.reduce((s,l)=>s+lineCost(l),0);const suggested=Number(f.target_food_cost_percent||0)>0?total/(Number(f.target_food_cost_percent)/100):0;function addLine(){setLines([...lines,{ingredient_id:'',quantity:'',unit_id:''}])}function updateLine(index:number,patch:Partial<{ingredient_id:string;quantity:string;unit_id:string}>){setLines(lines.map((l,i)=>{if(i!==index)return l;const next={...l,...patch};if(patch.ingredient_id){const ing=ingredients.find(x=>x.id===patch.ingredient_id);next.unit_id=ing?.unit_id||''}return next}))}function removeLine(index:number){setLines(lines.filter((_,i)=>i!==index))}async function save(e:FormEvent){e.preventDefault();if(!supabase)return;if(!f.category)return alert('Seleziona una categoria per la ricetta.');if(lines.some(l=>!l.ingredient_id||!l.unit_id||Number(l.quantity)<=0))return alert('Completa ingrediente, quantità e unità di misura per ogni riga.');setSaving(true);const payload={recipe_collection:recipe?.recipe_collection||collection,name:f.name,category:f.category,standard_portions:1,target_food_cost_percent:f.target_food_cost_percent?Number(f.target_food_cost_percent):null,manual_sale_price:f.manual_sale_price?Number(f.manual_sale_price):null,procedure:f.procedure||null,notes:f.notes||null};let recipeId=recipe?.id||'';if(recipe){const{error}=await supabase.from('recipes').update(payload).eq('id',recipe.id);if(error){setSaving(false);return alert(error.message)}}else{const{data,error}=await supabase.from('recipes').insert(payload).select('id').single();if(error){setSaving(false);return alert(error.message)}recipeId=(data as any).id}const del=await supabase.from('recipe_ingredients').delete().eq('recipe_id',recipeId);if(del.error){setSaving(false);return alert(del.error.message)}if(lines.length){const rows=lines.map((l,idx)=>({recipe_id:recipeId,ingredient_id:l.ingredient_id,quantity:Number(l.quantity),unit_id:l.unit_id,sort_order:idx}));const ins=await supabase.from('recipe_ingredients').insert(rows);if(ins.error){setSaving(false);return alert(ins.error.message)}}setSaving(false);await onSaved();onClose()}return <Modal title={recipe?recipe.name:'Nuova ricetta'} onClose={onClose} wide><form onSubmit={save} className="recipeEditor"><span className="eyebrow">{(recipe?.recipe_collection||collection)==='a_la_carte'?'À LA CARTE':'BANCHETTI'}</span><div className="formGrid recipeBasics"><label className="span2">Nome piatto<input required value={f.name} onChange={e=>setF({...f,name:e.target.value})}/></label><div className="recipePricingRow span2"><label>Categoria<select required value={f.category} onChange={e=>setF({...f,category:e.target.value})}><option value="">Seleziona categoria</option>{RECIPE_CATEGORIES.map(category=><option key={category} value={category}>{category}</option>)}</select></label><label>Food cost target %<input type="number" min="1" max="100" step="0.1" value={f.target_food_cost_percent} onChange={e=>setF({...f,target_food_cost_percent:e.target.value})}/></label><label>Prezzo di vendita forzato €<input type="number" min="0" step="0.01" value={f.manual_sale_price} onChange={e=>setF({...f,manual_sale_price:e.target.value})}/></label></div></div><div className="recipeWork"><section className="compositionBox"><div className="compositionHead"><div><span className="eyebrow">RICETTA E COMPOSIZIONE</span><h3>Ingredienti necessari</h3></div><button type="button" className="secondary" onClick={addLine}><Plus size={16}/> Ingrediente</button></div>{lines.length===0?<Empty text="Aggiungi gli ingredienti della ricetta."/>:<div className="ingredientEditorList"><div className="ingredientEditorHeader"><span>Ingrediente</span><span>Quantità</span><span>Unità</span><span>Costo unit.</span><span>Subtotale</span><span></span></div>{lines.map((l,idx)=>{const ing=ingredients.find(i=>i.id===l.ingredient_id);const hyd=hydratedLines[idx];return <div className="ingredientEditorRow" key={idx}><select value={l.ingredient_id} onChange={e=>updateLine(idx,{ingredient_id:e.target.value})}><option value="">Seleziona ingrediente</option>{ingredients.filter(i=>i.active).map(i=><option key={i.id} value={i.id}>{i.name}</option>)}</select><input type="number" min="0" step="0.0001" value={l.quantity} onChange={e=>updateLine(idx,{quantity:e.target.value})} placeholder="0"/><select value={l.unit_id} onChange={e=>updateLine(idx,{unit_id:e.target.value})}><option value="">Unità</option>{units.map(u=><option key={u.id} value={u.id}>{u.code}</option>)}</select><span>{ing?`${euro(ing.current_price)} / ${ing.unit?.code||''}`:'—'}</span><strong>{euro(lineCost(hyd))}</strong><button type="button" className="deleteLine" onClick={()=>removeLine(idx)}><Trash2 size={16}/></button></div>})}<div className="recipeTotal"><span>Totale materie prime</span><strong>{euro(total)}</strong></div></div>}</section><aside className="costPanel"><span>PREZZO DI VENDITA CONSIGLIATO</span><strong>{suggested?euro(suggested):'—'}</strong><div className="costRows"><div><span>Costo food reale</span><b>{euro(total)}</b></div><div><span>Food cost target</span><b>{f.target_food_cost_percent?`${f.target_food_cost_percent}%`:'—'}</b></div></div></aside></div><div className="formGrid recipeNotes"><label className="span2">Procedimento<textarea rows={5} value={f.procedure} onChange={e=>setF({...f,procedure:e.target.value})} placeholder="Procedimento di preparazione…"/></label><label className="span2">Note<textarea rows={3} value={f.notes} onChange={e=>setF({...f,notes:e.target.value})}/></label></div><div className="formActions recipeActions"><button type="button" className="ghost" onClick={onClose}>Annulla</button><button className="primary" disabled={saving}>{saving?'Salvataggio…':recipe?'Salva modifiche':'Salva ricetta'}</button></div></form></Modal>}
